informationNeed.text:
PREFIX zaguan: 
PREFIX text: 

SELECT DISTINCT ?doc
WHERE {
    {
        ?doc text:query "López AND author" .
    } UNION {
        ?doc text:query "López AND contributor" .
    }
    ?doc zaguan:publisher ?ent .
    ?ent zaguan:nombreEntidad "Informática" .

    ?doc rdf:type ?type .
    FILTER (?type = zaguan:TFG || ?type = zaguan:TFM)
}
LIMIT 100
